9cff064.90660918.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-07T19:26:33+00:00","updated_at":"2026-03-07T19:26:33+00:00"},{"legacy_id":639,"nombre":"Martina Lavia","email":"martinabiscoqueso@gmail.com","telefono":"2645306226","puesto":"Fotografía, comunicación social e iluminación.","categoria_puesto":"","mensaje":"Soy Martina Lavia, Estudiante de Fotografía en La Escuela Nacional de Fotografía, (ENFO) y Diplomada Universitaria en fotografía técnica y documental.\r\nMi búsqueda es por fotos con textura, rugosidad, colores vivos, saturados e intensos, la búsqueda de líneas, puntos de fuga y de composiciones con simetría,\r\nHe trabajado con diferentes artistas y en colaboraciones con otros fotógrafos, como en el colectivo “La Combi”, Milité durante años en un Partido político al cuál hice las veces de fotografa. \r\nTengo dos grandes mentores: Daniel Merle profesor mío de la Universidad (periodista del diario La nación) y mi amiga Valentina Gangemi (egresada de la Univ. de Córdoba).\r\nEllos su camaradería y sus enseñanzas me han permitido ir paso a paso en este camino que, espero continue por muchos años.","cv_url":"https://bwdtrzcdzbzrtykjzber.supabase.co/storage/v1/object/public/archivos/cv-postulaciones/legacy_639_cv_69af9ccc1714b5.29293009.pdf","cv_nombre":"cv_69af9ccc1714b5.29293009.pdf","cv_mime":"application/pdf","estado":"nuevo","notas_rrhh":"","metadata_ia":{"imported_from":"php_postulaciones","legacy_status":"Nuevo","legacy_cv_ruta":"uploads/cv/cv_69af9ccc1714b5.29293009.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-10T04:23:40+00:00","updated_at":"2026-03-10T04:23:40+00:00"},{"legacy_id":640,"nombre":"Enzo Ariel Martinez","email":"enzo22898@gmail.com","telefono":"2645565956","puesto":"Dispuesto a cualquier oportunidad laboral","categoria_puesto":"","mensaje":"Estimado/a \r\nMe gustaría presentar mi candidatura espontánea para futuros procesos de selección en Plot Center.\r\nAdmiro su trayectoria en campo laboral y tengo un gran interés en formar parte y contribuir a proyectos de la empresa.\r\nAdjunto mi CV y quedo a plena disposición.\r\nUn cordial saludo,","cv_url":"https://bwdtrzcdzbzrtykjzber.supabase.co/storage/v1/object/public/archivos/cv-postulaciones/legacy_640_cv_69b064a3bbbbf2.53132825.pdf","cv_nombre":"cv_69b064a3bbbbf2.53132825.pdf","cv_mime":"application/pdf","estado":"nuevo","notas_rrhh":"","metadata_ia":{"imported_from":"php_postulaciones","legacy_status":"Nuevo","legacy_cv_ruta":"uploads/cv/cv_69b064a3bbbbf2.53132825.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-10T18:36:19+00:00","updated_at":"2026-03-10T18:36:19+00:00"},{"legacy_id":641,"nombre":"Cecilia Beatriz Martinez","email":"mrtnz.ceci@gmail.com","telefono":"02644604336","puesto":"Diseñador/a Gráfico/a Junior","categoria_puesto":"","mensaje":"Mi nombre es Cecilia Martinez y me comunico para ofrecer mis servicios de diseño gráfico, producción e impresión.\r\n\r\nCuento con experiencia en el desarrollo de soluciones gráficas integrales, adaptadas a las necesidades y objetivos de cada proyecto, tanto para marcas, empresas y eventos. Trabajo de manera personalizada, acompañando cada etapa del proceso creativo y productivo para lograr resultados efectivos y de calidad.\r\n\r\nQuedo a disposición para enviar mi portfolio, realizar presupuestos personalizados o coordinar una reunión para ampliar esta información.\r\n\r\nServicios:\r\nhttps://drive.google.com/drive/folders/1gtpHzBMpUiOzhTc-7I308_NrytW_-gpk\r\n\r\nInstagram:\r\nhttps://www.instagram.com/dgmartinezcecilia\r\nwww.behance.net/cbmartinez\r\n\r\nSaludos cordiales,\r\nCecilia Martinez\r\nDiseño Gráfico · Producción · Impresión","cv_url":"https://bwdtrzcdzbzrtykjzber.supabase.co/storage/v1/object/public/archivos/cv-postulaciones/legacy_641_cv_69b1cb43808f40.49763187.pdf","cv_nombre":"cv_69b1cb43808f40.49763187.pdf","cv_mime":"application/pdf","estado":"nuevo","notas_rrhh":"","metadata_ia":{"imported_from":"php_postulaciones","legacy_status":"Nuevo","legacy_cv_ruta":"uploads/cv/cv_69b1cb43808f40.49763187.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-11T20:06:27+00:00","updated_at":"2026-03-11T20:06:27+00:00"},{"legacy_id":642,"nombre":"Manzano","email":"posmarianela@gmail.com","telefono":"2645603009","puesto":"Cajero/a","categoria_puesto":"","mensaje":"Me encuentro en búsqueda laboral y quería postularme para el puesto. Cuento con experiencia en facturación y atención en caja, manejo de cobros y trato con clientes. Me considero una persona responsable, organizada y con buena predisposición para el trabajo. Quedo a disposición para ampliar información. Muchas gracias.","cv_url":"https://bwdtrzcdzbzrtykjzber.supabase.co/storage/v1/object/public/archivos/cv-postulaciones/legacy_642_cv_69b240a25515e7.67620843.pdf","cv_nombre":"cv_69b240a25515e7.67620843.pdf","cv_mime":"application/pdf","estado":"nuevo","notas_rrhh":"","metadata_ia":{"imported_from":"php_postulaciones","legacy_status":"Nuevo","legacy_cv_ruta":"uploads/cv/cv_69b240a25515e7.67620843.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-12T04:27:14+00:00","updated_at":"2026-03-12T04:27:14+00:00"},{"legacy_id":645,"nombre":"Mayra Marcuzzi","email":"mayramar@hotmail.com.ar","telefono":"2646629523","puesto":"Atención al Cliente","categoria_puesto":"","mensaje":"Buenas tardes, estoy en búsqueda de experiencia laboral en el rubro de las gráficas, estudié marketing y me gusta todo lo orientado a diseño.","cv_url":"https://bwdtrzcdzbzrtykjzber.supabase.co/storage/v1/object/public/archivos/cv-postulaciones/legacy_645_cv_69b304cf693d39.43326654.pdf","cv_nombre":"cv_69b304cf693d39.43326654.pdf","cv_mime":"application/pdf","estado":"nuevo","notas_rrhh":"","metadata_ia":{"imported_from":"php_postulaciones","legacy_status":"Nuevo","legacy_cv_ruta":"uploads/cv/cv_69b304cf693d39.43326654.pdf","migrated_at":"2026-06-09T11:25:27.158Z"},"created_at":"2026-03-12T18:24:15+00:00","updated_at":"2026-03-12T18: